text:
/* Forge-only presentation. Native TiddlyWiki controls, editor and saver remain. */
html body.tc-body {background:#f3f2ed;color:#163d46;}
.tc-story-river {max-width:1180px;}
.tc-tiddler-frame[data-tiddler-title="HUWiki Forge"] {background:transparent;border:0;box-shadow:none;padding:0 28px 36px;}
.tc-tiddler-frame[data-tiddler-title="HUWiki Forge"] .tc-titlebar {padding:0;margin-bottom:8px;}
.tc-tiddler-frame[data-tiddler-title="HUWiki Forge"] .tc-titlebar h2 {font-size:14px;letter-spacing:.01em;color:#5c6b61;}
.forge-home {--forge-ink:#163d46;--forge-muted:#465e64;--forge-line:#d5dcd3;color:var(--forge-ink);}
.forge-home * {box-sizing:border-box;}
.forge-hero {padding:24px 0 28px;border-bottom:1px solid var(--forge-line);}
.forge-eyebrow {display:flex;align-items:center;gap:10px;font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;}
.forge-mark {display:inline-flex;align-items:center;justify-content:center;width:34px;height:36px;border-radius:8px;background:#c9eddb;color:#163d46;font-size:25px;letter-spacing:-.06em;}
.forge-kicker {color:var(--forge-muted);font-weight:500;}
.forge-home .forge-hero h1 {font-family:Georgia,"Times New Roman",serif;font-size:clamp(42px,5vw,76px);font-weight:400;line-height:1.04;letter-spacing:-.055em;margin:28px 0 20px;max-width:650px;color:var(--forge-ink);}
.forge-lead {font-size:18px;line-height:1.65;max-width:570px;color:var(--forge-muted);margin:0 0 24px;}
.forge-facts {display:flex;flex-wrap:wrap;gap:8px 18px;font-size:11px;color:var(--forge-muted);}
.forge-facts span:before {content:"✓";margin-right:6px;color:#356c49;}
.forge-section-head {padding:32px 0 20px;}
.forge-home h2 {font-size:26px;font-weight:600;letter-spacing:-.035em;margin:8px 0;}
.forge-section-head p,.forge-next p,.forge-footer p {font-size:13px;color:var(--forge-muted);line-height:1.7;}
.forge-grid {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px;}
.forge-card {display:flex;flex-direction:column;min-width:0;background:#fffefa;border:1px solid var(--forge-line);border-radius:14px;padding:23px;}
.forge-card-top {display:flex;align-items:center;justify-content:space-between;margin-bottom:24px;}
.forge-number {font-family:Georgia,serif;font-size:24px;color:#809283;}
.forge-status {font-size:10px;font-weight:600;background:#f3ead3;color:#715321;border-radius:20px;padding:3px 9px;}
.forge-edition-name {font-size:10px;letter-spacing:.07em;text-transform:uppercase;color:var(--forge-muted);}
.forge-home .forge-card h3 {font-size:23px;font-weight:600;letter-spacing:-.04em;line-height:1.2;margin:10px 0;}
.forge-card .forge-description {font-size:13px;line-height:1.7;color:var(--forge-muted);margin:0 0 15px;}
.forge-card .forge-note {font-size:11px;line-height:1.6;color:#76634a;margin:auto 0 18px;}
.forge-card-action {display:flex;justify-content:space-between;align-items:center;padding-top:13px;border-top:1px solid var(--forge-line);font-size:12px;font-weight:700;}
.forge-home a {color:var(--forge-ink);text-decoration:none;}
.forge-home a:hover {text-decoration:underline;}
.forge-card:focus-within {outline:2px solid #356c49;outline-offset:3px;}
.forge-next {display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-top:32px;padding:28px;border-radius:14px;background:#e8f0ea;}
.forge-library-links {align-self:center;min-width:0;}
.forge-home .forge-library {display:flex;justify-content:space-between;width:100%;text-align:left;background:transparent;border:0;border-bottom:1px solid #b5c4b4;border-radius:0;padding:12px 0;font-size:12px;font-weight:650;color:var(--forge-ink);white-space:normal;}
.forge-home .forge-small {font-size:11px;}
.forge-footer {margin-top:32px;padding-top:12px;max-width:650px;}
.forge-home .forge-save {background:#163d46;color:#fff;border:0;border-radius:8px;font-size:12px;padding:12px 18px;margin:5px 0 12px;}
@media(min-width:1100px){.tc-story-river{width:calc(100% - 320px);}.tc-sidebar-scrollable{width:290px;}}
@media(max-width:700px){.forge-grid,.forge-next{grid-template-columns:1fr}.tc-tiddler-frame[data-tiddler-title="HUWiki Forge"]{padding:0 8px 24px}.forge-home .forge-hero h1{font-size:46px}.forge-kicker{display:none}.forge-lead{font-size:16px}.forge-card{padding:20px}.forge-next{padding:22px;gap:10px}.forge-card-top{margin-bottom:14px}}

.forge-grid > p {display:contents;}

/* Readability pass inspired by HUWiki's teal/mint palette and readable type. */
.forge-hero {background:linear-gradient(115deg,#153b46,#20525a);color:#fffef9;padding:30px 32px;border-radius:16px;border:0;}
.forge-home .forge-hero h1 {color:#fffef9;font-size:clamp(40px,4.5vw,64px);max-width:760px;margin:24px 0 18px;}
.forge-hero .forge-lead {color:#edf4ef;font-size:19px;max-width:650px;}
.forge-hero .forge-small,.forge-hero .forge-facts,.forge-hero .forge-kicker {color:#d0e6dc;}
.forge-hero .forge-facts span:before {color:#c9eddb;}
.forge-facts,.forge-home .forge-small {font-size:13px;line-height:1.65;}
.forge-section-head p,.forge-next p,.forge-footer p {font-size:16px;line-height:1.65;max-width:68ch;}
.forge-eyebrow {font-size:12px;}
.forge-section-head {padding-bottom:4px;}
.forge-test-intro {font-size:14px;line-height:1.6;color:#6b592e;margin:0 0 24px;max-width:72ch;}
.forge-card .forge-description {font-size:16px;line-height:1.65;}
.forge-card .forge-note {font-size:14px;line-height:1.6;}
.forge-edition-name {font-size:13px;letter-spacing:.03em;}
.forge-status {font-size:12px;}
.forge-card-action,.forge-home .forge-library,.forge-home .forge-save {font-size:15px;line-height:1.5;}
.forge-home .forge-library {min-height:48px;}
.forge-card-action {min-height:48px;}
.tc-site-title {color:#163d46;}
.tc-site-subtitle,.tc-sidebar-header {color:#465e64;}
@media(max-width:700px){.forge-hero{padding:24px 20px}.forge-home .forge-hero h1{font-size:40px}.forge-hero .forge-lead{font-size:17px}.forge-card .forge-description{font-size:16px}}
